
/* Récap du Camp — scènes animées.
   Place les fichiers dans le dossier « recap/ » à côté de l'app :
   scene1.mp4 … scene6.mp4 (vidéos 9:16 de 5 s) et/ou scene1.jpg … scene6.jpg (images sans texte).
   Si un fichier est absent, la scène garde son fond actuel : rien ne casse. */
(function(){
var BASE=(window.RECAP_MEDIA_BASE||'recap/');
/* numéro de diapo du récap (0 = première) → numéro de scène */
var MAP=window.RECAP_SCENES||{0:7,4:1,5:2,6:3,8:4,9:5,10:6,11:7};
var EMB={"1": "data:image/jpeg;base64,", "2": "data:image/jpeg;base64,", "3": "data:image/jpeg;base64,", "4": "data:image/jpeg;base64,", "5": "data:image/jpeg;base64,", "6": "data:image/jpeg;base64,", "7": "data:image/jpeg;base64,"};
var reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
var save=false;try{save=!!(navigator.connection&&navigator.connection.saveData)}catch(e){}
var cur=null;
function banner(){var cd=document.getElementById('v51Cd');if(!cd||document.getElementById('rfBanner'))return;
 var s=document.createElement('section');s.id='rfBanner';s.setAttribute('aria-label','Récap du Camp');
 s.innerHTML='<button type="button" class="rfb" aria-label="Ouvrir le récap du Camp"><img alt="" src="'+EMB[7]+'"><span class="rfp"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.5v13l11-6.5z"/></svg></span></button>';
 cd.parentNode.insertBefore(s,cd);
 s.querySelector('.rfb').addEventListener('click',function(){var sc=document.getElementById('v58Scene');if(sc)sc.click()})}
banner();

function build(rc){
 var bg=document.createElement('div');bg.className='rc-bg rf-none';bg.setAttribute('aria-hidden','true');
 rc.insertBefore(bg,rc.firstChild);
 var items={},idx=-1,paused=false;
 function mk(n){
  if(items[n])return items[n];
  var box=document.createElement('div'),it={box:box,v:null,ok:false};box.className='rf';
  function img(){var im=new Image();im.alt='';im.decoding='async';
   im.onload=function(){box.appendChild(im);it.ok=true;refresh()};
   im.onerror=function(){var e=EMB[n];if(!e){it.ok=false;return}var p=new Image();p.alt='';p.className='pic p'+n;
    p.onload=function(){box.classList.add('pic');box.appendChild(p);it.ok=true;refresh()};p.src=e};im.src=BASE+'scene'+n+'.jpg'}
  if(reduce||save||n===7){img()}
  else{var v=document.createElement('video');v.muted=true;v.defaultMuted=true;v.loop=true;v.playsInline=true;
   v.setAttribute('playsinline','');v.setAttribute('muted','');v.preload='auto';it.v=v;
   v.addEventListener('loadeddata',function(){box.appendChild(v);it.ok=true;refresh()},{once:true});
   v.addEventListener('error',function(){it.v=null;img()},{once:true});
   v.src=BASE+'scene'+n+'.mp4'}
  bg.appendChild(box);items[n]=it;return it}
 function refresh(){
  var n=MAP[idx],any=false;
  Object.keys(items).forEach(function(k){var it=items[k],on=(+k===n&&it.ok);
   it.box.classList.toggle('on',on);if(on)any=true;
   if(it.v){if(on){if(!paused){try{it.v.play()}catch(e){}}}else{try{it.v.pause()}catch(e){}}}});
  bg.classList.toggle('rf-none',!any)}
 function show(i){if(i===idx)return;idx=i;var n=MAP[i];
  if(n){var it=mk(n);if(it.v&&it.ok){try{it.v.currentTime=0}catch(e){}}
   var nx=MAP[i+1]||MAP[i+2];if(nx)mk(nx)}
  refresh()}
 function active(){var s=[].slice.call(rc.querySelectorAll('.rc-s'));for(var k=0;k<s.length;k++)if(s[k].classList.contains('on'))return k;return -1}
 var st=rc.querySelector('.rc-st');
 var mo=new MutationObserver(function(){var a=active();if(a>=0)show(a)});
 if(st)mo.observe(st,{subtree:true,attributes:true,attributeFilter:['class']});
 show(Math.max(0,active()));
 rc.addEventListener('pointerdown',function(e){if(e.target.closest('button'))return;paused=true;refresh()});
 function up(){if(!paused)return;paused=false;refresh()}
 rc.addEventListener('pointerup',up);rc.addEventListener('pointercancel',up);
 return {stop:function(){mo.disconnect();Object.keys(items).forEach(function(k){var v=items[k].v;if(v){try{v.pause();v.removeAttribute('src');v.load()}catch(e){}}})}}}
new MutationObserver(function(ms){ms.forEach(function(m){
 m.addedNodes.forEach(function(n){if(n.nodeType===1&&n.classList&&n.classList.contains('rc')&&!n.querySelector('.rc-bg'))cur=build(n)});
 m.removedNodes.forEach(function(n){if(n.nodeType===1&&n.classList&&n.classList.contains('rc')&&cur){cur.stop();cur=null}})})
}).observe(document.body,{childList:true});
})();
